(1450, 'global', '/ˈɡloʊbəl/', 'adjective', '{"zh-TW":["全球的"],"en":["relating to the whole world"]}', NULL, 'global market/economy', '[{"en":"The company has a global presence.","zh-TW":"該公司在全球有業務。"},{"en":"Global trade continues to expand.","zh-TW":"全球貿易持續擴張。"}]', '{"noun":"globalization","adjective":"global","adverb":"globally"}', NULL, 2, 1450, 879),
