(1452, 'gluten-free', '/ˌɡluːtən ˈfriː/', 'adjective', '{"zh-TW":["無麩質的"],"en":["containing no gluten"]}', NULL, 'gluten-free menu / gluten-free option', '[{"en":"We offer a gluten-free menu for sensitive guests.","zh-TW":"我們為敏感的賓客提供無麩質菜單。"},{"en":"Please request a gluten-free dish when making your reservation.","zh-TW":"訂位時請要求無麩質餐點。"}]', NULL, NULL, 4, 1452, NULL),
