(1454, 'go-live', '/ɡoʊ laɪv/', 'noun', '{"zh-TW":["上線；啟用"],"en":["the date when a system or product is made available to users"]}', NULL, 'go-live date / prepare for go-live / post go-live support', '[{"en":"The go-live was delayed by two weeks due to testing issues.","zh-TW":"由於測試問題，上線日期推遲了兩週。"},{"en":"Extensive training was provided before the system go-live.","zh-TW":"系統上線前提供了廣泛的培訓。"}]', '{"verb":"go live"}', NULL, 3, 1454, NULL),
