(1460, 'gourmet', '/ˈɡʊərmeɪ/', 'adjective', '{"zh-TW":["美食的；精緻的"],"en":["of a high quality or sophisticated standard"]}', NULL, 'gourmet restaurant / gourmet food', '[{"en":"The hotel''s gourmet restaurant has three Michelin stars.","zh-TW":"飯店的美食餐廳獲得了三顆米其林星。"},{"en":"They offer a gourmet tasting menu every weekend.","zh-TW":"他們每個週末提供精緻試菜菜單。"}]', '{"noun":"gourmet"}', NULL, 3, 1460, NULL),
(1461, 'govern', '/ˈɡʌvərn/', 'verb', '{"zh-TW":["治理；管理","統治；管理"],"en":["to control and direct public affairs; to regulate","to officially control a country or organization"]}', NULL, 'govern by rules/laws; govern a country / governing body', '[{"en":"The country is governed by a democratic system.","zh-TW":"該國由民主制度治理。"},{"en":"Clear rules govern the use of company assets.","zh-TW":"明確的規則管理公司資產的使用。"},{"en":"The country is governed by a president.","zh-TW":"這個國家由總統統治。"},{"en":"Laws govern how businesses operate.","zh-TW":"法律規範企業的營運方式。"}]', '{"noun":"government/governance/governor","verb":"govern","noun2":"governor","noun3":"governance"}', NULL, 2, 1461, 689),
