(1464, 'grace', '/ɡreɪs/', 'noun', '{"zh-TW":["寬限；優雅"],"en":["a period of extra time; elegance"]}', NULL, 'grace period', '[{"en":"There is a 30-day grace period for payment.","zh-TW":"有30天的寬限期付款。"},{"en":"She handled the crisis with grace.","zh-TW":"她優雅地處理了危機。"}]', '{"noun":"grace","adjective":"graceful/gracious"}', NULL, 2, 1464, NULL),
