(1470, 'grateful', '/ˈɡreɪtfəl/', 'adjective', '{"zh-TW":["感激的"],"en":["feeling thankful","feeling or showing thanks"]}', '{"root":{"text":"grat","meaning":"pleasing (令人愉悅)"},"suffix":{"text":"-ful","meaning":"full of (充滿)"},"logic":"充滿感謝之情的。"}', 'grateful for/to; grateful for / deeply grateful', '[{"en":"We are grateful for your continued support.","zh-TW":"我們感謝您持續的支持。"},{"en":"I would be grateful if you could reply promptly.","zh-TW":"如果您能及時回覆，我將不勝感激。"},{"en":"I''m grateful for your help.","zh-TW":"我很感激你的幫助。"},{"en":"She was deeply grateful to her mentor.","zh-TW":"她對她的導師深懷感激。"}]', '{"noun":"gratitude","adjective":"grateful","adverb":"gratefully"}', NULL, 3, 1470, NULL),
(1471, 'gratuity', '/ɡrəˈtjuːɪti/', 'noun', '{"zh-TW":["小費；服務費"],"en":["a sum of money given as a tip for service"]}', NULL, 'add a gratuity / include gratuity', '[{"en":"A 15% gratuity is automatically added to the bill.","zh-TW":"帳單自動加收15%服務費。"},{"en":"It is customary to leave a gratuity for good service.","zh-TW":"留下小費給優質服務是一種習慣。"}]', '{"verb":"gratify","adjective":"gratuitous"}', NULL, 3, 1471, NULL),
(1472, 'grave', '/ɡreɪv/', 'adjective', '{"zh-TW":["嚴重的；嚴肅的"],"en":["serious; giving cause for concern"]}', NULL, 'grave concern/consequences', '[{"en":"This is a matter of grave concern.","zh-TW":"這是一件令人嚴重關切的事。"},{"en":"The error could have grave consequences.","zh-TW":"這個錯誤可能有嚴重的後果。"}]', '{"noun":"gravity","adjective":"grave","adverb":"gravely"}', NULL, 2, 1472, NULL),
