(1476, 'grievance', '/ˈɡriːvəns/', 'noun', '{"zh-TW":["申訴；不滿"],"en":["a formal complaint by an employee about a workplace issue"]}', NULL, 'file a grievance / grievance procedure / handle grievances', '[{"en":"She filed a grievance against her manager for unfair treatment.","zh-TW":"她就不公平對待向主管提出申訴。"},{"en":"The company has a formal grievance procedure for employees.","zh-TW":"公司有正式的員工申訴程序。"}]', '{"verb":"grieve","adjective":"aggrieved"}', NULL, 3, 1476, NULL),
