(1478, 'ground', '/ɡraʊnd/', 'noun', '{"zh-TW":["【主要意義-名詞】地面；土地","【次要意義-動詞】擱置；禁止（飛機）起飛","【次要意義-動詞】教導基礎；使打好根基","【次要意義-名詞（複數）】理由；根據；依據"],"en":["[primary - noun] the surface of the earth","[secondary - verb] to keep an aircraft from flying; to confine to one place","[secondary - verb] to teach someone the basic principles of a subject","[secondary - plural noun] a reason or justification for something"]}', NULL, 'grounds for dismissal / well-grounded / ground floor / break new ground / on the grounds that', '[{"en":"All flights were grounded due to the severe weather conditions.","zh-TW":"由於惡劣天氣，所有航班被迫停飛。"},{"en":"The dismissal was challenged on the grounds that proper procedures were not followed.","zh-TW":"解雇被以未遵守適當程序為由提出異議。"},{"en":"New employees are grounded in company policy during their first week.","zh-TW":"新員工在第一週接受公司政策的基礎培訓。"}]', '{"noun":"groundwork, groundbreaking","adjective":"grounded"}', 'grounds（複數）= 「理由/根據」（grounds for dismissal = 解雇理由），on the grounds that（以……為由），動詞 ground = 「擱置/打基礎」均是 TOEIC 法律和人事文章的必考用法。', 2, 1478, NULL),
