(1483, 'guarantee', '/ˌɡærənˈtiː/', 'noun / verb', '{"zh-TW":["保證；擔保"],"en":["a formal promise; to give a guarantee","a promise that something will be done or will happen"]}', '{"root":{"text":"garant","meaning":"warrant (擔保)"},"logic":"給予擔保的承諾。"}', 'money-back guarantee; money-back guarantee / under guarantee', '[{"en":"The product comes with a two-year guarantee.","zh-TW":"產品附有兩年保固。"},{"en":"We guarantee delivery within 48 hours.","zh-TW":"我們保證48小時內送達。"},{"en":"The product comes with a two-year guarantee.","zh-TW":"該產品附有兩年保固。"},{"en":"There is no guarantee of success.","zh-TW":"沒有成功的保證。"}]', '{"noun":"guarantee/guarantor","verb":"guarantee"}', NULL, 3, 1483, 366),
(1484, 'guarantor', '/ˌɡærənˈtɔːr/', 'noun', '{"zh-TW":["擔保人"],"en":["a person or organization that agrees to be responsible for another''s debt or obligation"]}', NULL, 'provide a guarantor / act as guarantor', '[{"en":"The parent company acted as guarantor for the subsidiary''s bank loan.","zh-TW":"母公司為子公司的銀行貸款充當了擔保人。"},{"en":"A personal guarantor can be held liable if the business defaults on the loan.","zh-TW":"如果企業無法償還貸款，個人擔保人可能需要承擔責任。"}]', '{"verb":"guarantee","noun":"guarantee"}', NULL, 3, 1484, NULL),
(1485, 'guess', '/ɡɛs/', 'verb', '{"zh-TW":["猜測"],"en":["to estimate without certain knowledge"]}', NULL, 'I guess / rough guess', '[{"en":"I guess we need more time.","zh-TW":"我想我們需要更多時間。"},{"en":"At a rough guess, it costs about $5000.","zh-TW":"粗略估計大約要5000美元。"}]', '{"verb":"guess","noun":"guess","noun2":"guesswork"}', NULL, 2, 1485, NULL),
