(1489, 'guidelines', '/ˈɡaɪdlaɪnz/', 'noun', '{"zh-TW":["指導方針；準則"],"en":["rules or instructions providing direction"]}', NULL, 'follow guidelines / company guidelines', '[{"en":"Please follow the company guidelines when completing the form.","zh-TW":"填寫表格時請遵循公司指導方針。"},{"en":"New employees receive a copy of the workplace guidelines.","zh-TW":"新員工會收到一份工作場所準則副本。"}]', NULL, NULL, 4, 1489, NULL),
