(1494, 'hack', '/hæk/', 'verb', '{"zh-TW":["駭入；破解"],"en":["to gain unauthorized access to a computer"]}', NULL, 'hack into / life hack', '[{"en":"Someone hacked into the system.","zh-TW":"有人駭入了系統。"},{"en":"Here''s a useful life hack.","zh-TW":"這裡有一個實用的生活小技巧。"}]', '{"noun":"hacker","noun2":"hacking"}', NULL, 1, 1494, NULL),
(1495, 'hail', '/heɪl/', 'noun', '{"zh-TW":["冰雹"],"en":["pellets of frozen rain falling from clouds"]}', '{"root":{"text":"hail","meaning":"hailstone (冰雹)"},"logic":"指從雲中落下的冰粒。"}', 'hailstorm / hail damage', '[{"en":"The hail damaged several cars in the parking lot.","zh-TW":"冰雹損壞了停車場的幾輛車。"},{"en":"A sudden hailstorm caught everyone off guard.","zh-TW":"突如其來的冰雹讓所有人措手不及。"}]', '{"noun":"hailstorm"}', NULL, 1, 1495, NULL),
(1496, 'hair', '/hɛr/', 'noun', '{"zh-TW":["頭髮；毛髮"],"en":["the thin threads growing on the head"]}', NULL, 'hairstyle / hair salon', '[{"en":"She got a new hairstyle for the event.","zh-TW":"她為活動換了新髮型。"},{"en":"There is a hair salon downstairs.","zh-TW":"樓下有一間美髮沙龍。"}]', '{"noun":"hair","adjective":"hairy","noun2":"hairstyle"}', NULL, 1, 1496, NULL),
(1497, 'halal', '/həˈlɑːl/', 'adjective', '{"zh-TW":["清真的；合乎伊斯蘭教規的"],"en":["permissible according to Islamic law"]}', NULL, 'halal food / halal certified', '[{"en":"The restaurant serves halal food for Muslim guests.","zh-TW":"餐廳為穆斯林賓客提供清真食物。"},{"en":"Please indicate if you need a halal meal on the booking form.","zh-TW":"預訂表格上請說明是否需要清真餐食。"}]', NULL, NULL, 2, 1497, NULL),
(1498, 'half', '/hæf/', 'noun', '{"zh-TW":["一半"],"en":["one of two equal parts"]}', NULL, 'half price / first half', '[{"en":"The item is half price today.","zh-TW":"這個商品今天半價。"},{"en":"Revenue grew in the first half of the year.","zh-TW":"上半年營收成長了。"}]', '{"noun":"half","adjective":"half"}', NULL, 1, 1498, NULL),
(1499, 'halt', '/hɔːlt/', 'verb, noun', '{"zh-TW":["停止；中止","暫停"],"en":["to stop or cause to stop","a temporary stop"]}', NULL, 'come to a halt / halt production', '[{"en":"The project was halted due to budget cuts.","zh-TW":"該項目因預算削減而停止。"},{"en":"Traffic came to a halt during the storm.","zh-TW":"暴風雨期間交通完全停止。"}]', '{"noun":"halt","verb":"halt"}', NULL, 1, 1499, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1500, 'hamper', '/ˈhæmpər/', 'verb', '{"zh-TW":["妨礙；阻礙"],"en":["to prevent someone from easily doing something"]}', NULL, 'hamper progress/efforts/growth', '[{"en":"Bad weather hampered rescue efforts.","zh-TW":"惡劣天氣妨礙了救援工作。"},{"en":"Lack of funding hampered the research.","zh-TW":"缺乏資金阻礙了研究進展。"}]', '{"noun":"hamper","verb":"hamper"}', NULL, 2, 1500, NULL),
(1501, 'hand', '/hænd/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】手","【次要意義-動詞】傳遞；遞給","【次要意義-名詞】幫助；協助（a hand）","【次要意義-名詞】工人；勞動者"],"en":["[primary - noun] the body part at the end of the arm","[secondary - verb] to pass or give something to someone","[secondary - noun] help or assistance","[secondary - noun] a worker or employee, especially in manual work"]}', NULL, 'hand in / hand out / lend a hand / give someone a hand / first-hand / at hand', '[{"en":"Could you hand me the report that was submitted this morning?","zh-TW":"你能把今早提交的報告遞給我嗎？"},{"en":"All staff are required to hand in their reports by Friday.","zh-TW":"所有員工須在週五前繳交報告。"},{"en":"The warehouse hired extra hands to manage the holiday rush.","zh-TW":"倉庫僱用了額外的人手來應對假日旺季。"}]', '{"noun":"handout, handover, handbook","adjective":"hands-on"}', 'hand 作動詞表「遞交/傳遞」，hand in（繳交），hand out（分發），名詞 hand（工人/幫手）、first-hand（第一手的）均是 TOEIC 職場文章常見詞彙。', 1, 1501, NULL),
(1502, 'handbook', '/ˈhændbʊk/', 'noun', '{"zh-TW":["手冊；指南"],"en":["a book giving useful information or instructions"]}', NULL, 'employee handbook / reference handbook', '[{"en":"Please read the employee handbook before your first day.","zh-TW":"請在第一天上班前閱讀員工手冊。"},{"en":"The handbook covers all safety procedures.","zh-TW":"手冊涵蓋了所有安全程序。"}]', '{"noun":"handbook"}', NULL, 3, 1502, NULL),
(1503, 'handle', '/ˈhændl/', 'verb, noun', '{"zh-TW":["處理；應對","把手；手柄"],"en":["to deal with a situation","a part of an object designed to be held"]}', NULL, 'handle a situation/complaint/task', '[{"en":"She handled the crisis with great composure.","zh-TW":"她非常鎮定地處理了這場危機。"},{"en":"Please handle the package with care.","zh-TW":"請小心搬運這個包裹。"}]', '{"noun":"handler, handling","verb":"handle"}', NULL, 2, 1503, 130),
(1504, 'handout', '/ˈhændaʊt/', 'noun', '{"zh-TW":["講義；資料單"],"en":["a document distributed to participants in a meeting or class"]}', NULL, 'distribute handouts / prepare handouts', '[{"en":"The trainer prepared handouts summarizing the key points.","zh-TW":"培訓師準備了總結關鍵要點的講義。"},{"en":"Please review the handout before the session begins.","zh-TW":"請在課程開始前查看講義。"}]', NULL, NULL, 3, 1504, NULL),
(1505, 'handover', '/ˈhændˌoʊvər/', 'noun', '{"zh-TW":["移交；交接"],"en":["the transfer of responsibility from one person to another"]}', NULL, 'project handover / job handover / smooth handover', '[{"en":"A detailed handover document was prepared for the incoming manager.","zh-TW":"為接任的管理者準備了詳細的交接文件。"},{"en":"The handover of the project took two weeks to complete.","zh-TW":"項目的移交花了兩週時間完成。"}]', '{"verb":"hand over"}', NULL, 3, 1505, 881),
(1506, 'hands-on', 'hændz ɒn', 'adjective', '{"zh-TW":["實際操作的；動手的","親身參與的"],"en":["involving practical work","learning by doing"]}', NULL, 'hands-on experience/hands-on training', '[{"en":"This role requires hands-on experience.","zh-TW":"這個職位需要實際操作經驗。"}]', '{"adverb":"hands-on"}', NULL, 3, 1506, NULL),
(1507, 'happen', '/ˈhæpən/', 'verb', '{"zh-TW":["發生"],"en":["to take place; to occur"]}', NULL, 'happen to / what happened', '[{"en":"What happened at the meeting?","zh-TW":"會議上發生了什麼？"},{"en":"This should not happen again.","zh-TW":"這不應該再發生。"}]', '{"verb":"happen","noun":"happening"}', NULL, 2, 1507, NULL),
(1508, 'happy', '/ˈhæpi/', 'adjective', '{"zh-TW":["快樂的；滿意的"],"en":["feeling pleasure","satisfied"]}', NULL, 'happy to help / happy with', '[{"en":"I am happy to assist you.","zh-TW":"我很樂意協助你。"},{"en":"Are you happy with the result?","zh-TW":"你對結果滿意嗎？"}]', '{"adjective":"happy","noun":"happiness","adverb":"happily","adjective2":"unhappy"}', NULL, 2, 1508, NULL),
(1509, 'harass', '/həˈræs/', 'verb', '{"zh-TW":["騷擾；煩擾"],"en":["to subject to aggressive pressure or intimidation"]}', NULL, 'harass someone / sexually harass', '[{"en":"Employees who harass others will face disciplinary action.","zh-TW":"騷擾他人的員工將面臨紀律處分。"},{"en":"She was harassed by persistent sales calls.","zh-TW":"她被持續不斷的推銷電話所騷擾。"}]', '{"noun":"harassment","verb":"harass"}', NULL, 2, 1509, NULL),
(1510, 'harassment', '/həˈræsmənt/', 'noun', '{"zh-TW":["騷擾；煩擾"],"en":["aggressive pressure or intimidation"]}', NULL, 'sexual harassment / workplace harassment', '[{"en":"The company has a strict policy against workplace harassment.","zh-TW":"公司有嚴格的反職場騷擾政策。"},{"en":"She filed a complaint about harassment.","zh-TW":"她提出了騷擾投訴。"}]', '{"noun":"harassment","verb":"harass"}', NULL, 4, 1510, NULL),
(1511, 'harbor', '/ˈhɑːrbər/', 'noun, verb', '{"zh-TW":["港口；海港","懷有（想法或感覺）"],"en":["a sheltered area of water for ships","to hold a thought or feeling secretly"]}', NULL, 'harbor doubts/resentment', '[{"en":"The ship docked at the harbor.","zh-TW":"船停靠在港口。"},{"en":"She harbored doubts about the plan.","zh-TW":"她對這個計劃心存疑慮。"}]', '{"noun":"harbor","verb":"harbor"}', NULL, 2, 1511, NULL),
(1512, 'hard', '/hɑːrd/', 'adjective', '{"zh-TW":["【主要意義-形容詞】硬的；困難的","【次要意義-副詞】努力地；猛烈地；使勁地","【次要意義-形容詞】確鑿的；嚴厲的"],"en":["[primary - adjective] solid and firm; difficult","[secondary - adverb] with great effort or force","[secondary - adjective] definite and reliable; stern"]}', NULL, 'work hard / hard evidence / hard currency / hard sell / hard on the heels', '[{"en":"The team worked hard to meet the production deadline.","zh-TW":"團隊努力工作以趕上生產截止日期。"},{"en":"Hard evidence is needed before any accusations are made.","zh-TW":"在提出任何指控之前需要有確鑿的證據。"},{"en":"Competition followed hard on the heels of the product launch.","zh-TW":"競爭緊隨產品發布而來。"}]', '{"adverb":"hardly","noun":"hardship"}', 'hard 作副詞意為「努力地/猛烈地」（不可用 hardly 替換，hardly = 幾乎不），hard evidence = 確鑿證據，hard currency = 硬通貨，均是 TOEIC 商業報告的重要詞彙。', 1, 1512, NULL),
(1513, 'hardship', '/ˈhɑːrdʃɪp/', 'noun', '{"zh-TW":["艱難；困苦"],"en":["severe suffering or difficulty"]}', NULL, 'endure/face/suffer hardship', '[{"en":"Many families endured hardship during the recession.","zh-TW":"許多家庭在經濟衰退期間忍受了困苦。"},{"en":"Financial hardship forced them to relocate.","zh-TW":"經濟困難迫使他們搬遷。"}]', '{"noun":"hardship","adjective":"hard"}', NULL, 3, 1513, NULL),
(1514, 'hardware', '/ˈhɑːrdwɛər/', 'noun', '{"zh-TW":["硬體"],"en":["the physical components of a computer system"]}', NULL, 'computer hardware / upgrade hardware', '[{"en":"The company replaced its outdated hardware with new machines.","zh-TW":"公司用新機器替換了過時的硬體。"},{"en":"Hardware problems can cause system crashes.","zh-TW":"硬體問題可能導致系統崩潰。"}]', NULL, NULL, 3, 1514, NULL),
(1515, 'harm', '/hɑːrm/', 'noun, verb', '{"zh-TW":["傷害；損害"],"en":["physical or psychological injury or damage"]}', NULL, 'do harm / cause harm / come to harm', '[{"en":"Smoking can cause serious harm to your health.","zh-TW":"吸菸會對你的健康造成嚴重傷害。"},{"en":"The chemicals may harm the environment.","zh-TW":"這些化學物質可能會損害環境。"}]', '{"noun":"harm","adjective":"harmful, harmless","verb":"harm"}', NULL, 1, 1515, NULL),
(1516, 'harmonization', '/ˌhɑːrmənaɪˈzeɪʃən/', 'noun', '{"zh-TW":["調和；協調統一"],"en":["the process of standardizing rules or practices across different regions or entities"]}', NULL, 'harmonization of regulations / tax harmonization', '[{"en":"Harmonization of accounting standards simplifies global financial reporting.","zh-TW":"會計準則的調和簡化了全球財務報告。"},{"en":"Trade harmonization between the two countries reduced customs complexity.","zh-TW":"兩國之間的貿易調和降低了海關複雜性。"}]', '{"verb":"harmonize"}', NULL, 5, 1516, 790),
(1517, 'harmonize', '/ˈhɑːrmənaɪz/', 'verb', '{"zh-TW":["協調；使協調一致"],"en":["to bring into agreement or alignment"]}', NULL, 'harmonize regulations / harmonize reporting standards', '[{"en":"The two subsidiaries harmonized their accounting policies after the merger.","zh-TW":"合並後，兩家子公司協調了各自的會計政策。"},{"en":"International bodies work to harmonize global trade regulations.","zh-TW":"國際機構致力於協調全球貿易法規。"}]', '{"noun":"harmonization","adjective":"harmonized"}', NULL, 3, 1517, 691),
(1518, 'harmony', '/ˈhɑːrməni/', 'noun', '{"zh-TW":["和諧；融洽"],"en":["a state of peaceful agreement and cooperation"]}', NULL, 'in harmony with / live in harmony', '[{"en":"The team works in harmony to achieve goals.","zh-TW":"團隊和諧合作以達成目標。"},{"en":"We must live in harmony with nature.","zh-TW":"我們必須與自然和諧共處。"}]', '{"noun":"harmony","adjective":"harmonious","verb":"harmonize"}', NULL, 3, 1518, NULL),
(1519, 'harvest', '/ˈhɑːrvɪst/', 'noun, verb', '{"zh-TW":["收穫；收成"],"en":["the process of gathering crops","to collect crops from the fields"]}', NULL, 'harvest season / harvest crops', '[{"en":"The harvest was abundant this year.","zh-TW":"今年的收成很豐富。"},{"en":"Farmers harvest wheat in late summer.","zh-TW":"農民在夏末收割小麥。"}]', '{"noun":"harvest, harvester","verb":"harvest"}', NULL, 3, 1519, NULL),
(1520, 'hasten', '/ˈheɪsn/', 'verb', '{"zh-TW":["加速；催促"],"en":["to make something happen sooner or more quickly"]}', NULL, 'hasten the process / hasten to add', '[{"en":"The treatment hastened her recovery.","zh-TW":"這項治療加速了她的康復。"},{"en":"He hastened to assure them that everything was fine.","zh-TW":"他趕忙向他們保證一切都好。"}]', '{"noun":"haste","verb":"hasten","adjective":"hasty","adverb":"hastily"}', NULL, 2, 1520, NULL),
(1521, 'hate', '/heɪt/', 'verb', '{"zh-TW":["討厭；憎恨"],"en":["to dislike very strongly"]}', NULL, 'hate to say / hate speech', '[{"en":"I hate to say this, but we need to cut the budget.","zh-TW":"我不想這麼說，但我們需要削減預算。"},{"en":"The company has a zero-tolerance policy on hate speech.","zh-TW":"公司對仇恨言論零容忍。"}]', '{"verb":"hate","noun":"hate","noun2":"hatred","adjective":"hateful"}', NULL, 1, 1521, NULL),
(1522, 'hazard', '/ˈhæzərd/', 'noun, verb', '{"zh-TW":["危險；危害","冒險"],"en":["a danger or risk","to risk or venture something"]}', NULL, 'health/safety hazard / hazard a guess', '[{"en":"Wet floors are a safety hazard.","zh-TW":"濕滑的地板是安全隱患。"},{"en":"I would hazard a guess that sales will increase.","zh-TW":"我冒昧猜測銷售額會增加。"}]', '{"noun":"hazard","adjective":"hazardous","verb":"hazard"}', NULL, 2, 1522, NULL),
(1523, 'hazardous', '/ˈhæzərdəs/', 'adjective', '{"zh-TW":["危險的；有害的"],"en":["risky; involving danger"]}', NULL, 'hazardous materials/waste/conditions', '[{"en":"Workers must wear protective gear when handling hazardous materials.","zh-TW":"工人處理危險物質時必須穿戴防護裝備。"},{"en":"Driving in fog is extremely hazardous.","zh-TW":"在霧中駕駛極其危險。"}]', '{"noun":"hazard","adjective":"hazardous"}', NULL, 3, 1523, NULL),
(1524, 'head', '/hɛd/', 'noun', '{"zh-TW":["【主要意義-名詞】頭部","【次要意義-動詞】朝向某方向；率領；帶頭","【次要意義-名詞】首腦；領導人；負責人","【次要意義-動詞】（列表/組織）排在首位"],"en":["[primary - noun] the part of the body above the neck","[secondary - verb] to go in a particular direction; to lead or be in charge","[secondary - noun] the leader or top person in an organization","[secondary - verb] to be at the top of a list or group"]}', NULL, 'head a department / head for / head office / go to head / heads of agreement', '[{"en":"She heads the product development division at the headquarters.","zh-TW":"她主管總部的產品研發部門。"},{"en":"The delegation is heading for the conference center.","zh-TW":"代表團正前往會議中心。"},{"en":"Heads of agreement were signed before the full contract was drafted.","zh-TW":"在起草完整合約之前，雙方簽署了基本協議要點。"}]', '{"noun":"heading, headquarters","adjective":"head-on"}', '動詞 head = 「率領/主管」，head for = 「朝……方向前進」，head office = 「總公司」，heads of agreement = 「基本協議要點」（TOEIC 法律文章）均是常考用法。', 1, 1524, NULL),
(1525, 'headcount', '/ˈhedkaʊnt/', 'noun', '{"zh-TW":["人數；員工總數"],"en":["the total number of people employed"]}', NULL, 'reduce/increase headcount', '[{"en":"The company reduced its headcount by 10%.","zh-TW":"公司裁減了10%的員工。"},{"en":"Current headcount stands at 450 employees.","zh-TW":"目前員工總數為450人。"}]', '{"noun":"headcount"}', NULL, 3, 1525, NULL),
(1526, 'headhunter', '/ˈhedˌhʌntər/', 'noun', '{"zh-TW":["獵頭；招聘顧問"],"en":["a recruiter who seeks out highly qualified candidates for senior roles"]}', NULL, 'work with a headhunter / executive headhunter / hired by a headhunter', '[{"en":"The board appointed a headhunter to find their new CEO.","zh-TW":"董事會委託獵頭公司尋找新任執行長。"},{"en":"A headhunter approached her with an opportunity at a rival firm.","zh-TW":"一位獵頭以競爭對手公司的機會接觸了她。"}]', '{"plural":"headhunters","alternative":"executive search consultant"}', NULL, 4, 1526, NULL),
(1527, 'headhunting', '/ˈhedhʌntɪŋ/', 'noun', '{"zh-TW":["獵頭；高層人才招募"],"en":["the practice of recruiting senior executives through direct approach"]}', NULL, 'hire through headhunting / headhunting firm', '[{"en":"The company engaged a headhunting firm to find a new CFO.","zh-TW":"公司聘用了獵頭公司尋找新任首席財務官。"},{"en":"Headhunting is typically used for senior and specialized roles.","zh-TW":"獵頭通常用於高級和專業職位。"}]', '{"verb":"headhunt","noun":"headhunter"}', NULL, 4, 1527, NULL),
(1528, 'headline', '/ˈhedlaɪn/', 'noun, verb', '{"zh-TW":["頭條新聞；標題"],"en":["the title of a newspaper article; to be the main performer"]}', NULL, 'make headlines / headline news', '[{"en":"The merger made headlines worldwide.","zh-TW":"這次合併成為全球頭條新聞。"},{"en":"A famous singer will headline the concert.","zh-TW":"一位著名歌手將領銜這場音樂會。"}]', '{"noun":"headline","verb":"headline"}', NULL, 3, 1528, NULL),
(1529, 'headquarters', '/ˈhedˌkwɔːrtərz/', 'noun', '{"zh-TW":["總部；總公司"],"en":["the main office of an organization"]}', NULL, 'company/corporate headquarters', '[{"en":"The company moved its headquarters to New York.","zh-TW":"該公司將總部遷至紐約。"},{"en":"All major decisions are made at headquarters.","zh-TW":"所有重大決策都在總部做出。"}]', '{"noun":"headquarters"}', NULL, 4, 1529, 131),
(1530, 'headroom', '/ˈhedrʊm/', 'noun', '{"zh-TW":["空間；回旋餘地"],"en":["the room available for further growth or flexibility within limits"]}', NULL, 'financial headroom / regulatory headroom / operating headroom', '[{"en":"The company has enough financial headroom to fund the expansion.","zh-TW":"公司有足夠的財務空間為擴張提供資金。"},{"en":"Headroom in the credit facility allows for seasonal cash needs.","zh-TW":"信貸額度的回旋餘地滿足了季節性現金需求。"}]', NULL, NULL, 3, 1530, NULL),
(1531, 'health', '/hɛlθ/', 'noun', '{"zh-TW":["健康"],"en":["the state of being well"]}', NULL, 'health insurance / public health', '[{"en":"The company provides health insurance.","zh-TW":"公司提供健康保險。"},{"en":"Public health is a top priority.","zh-TW":"公共衛生是首要之務。"}]', '{"noun":"health","adjective":"healthy","adverb":"healthily","adjective2":"unhealthy"}', NULL, 2, 1531, NULL),
(1532, 'hear', '/hɪr/', 'verb', '{"zh-TW":["聽到；聽說"],"en":["to perceive sound","to learn about"]}', NULL, 'hear from / glad to hear', '[{"en":"I look forward to hearing from you.","zh-TW":"我期待收到你的回覆。"},{"en":"I heard the news this morning.","zh-TW":"我今早聽到了這個消息。"}]', '{"verb":"hear","noun":"hearing"}', NULL, 1, 1532, NULL),
(1533, 'heart', '/hɑːrt/', 'noun', '{"zh-TW":["心臟；核心"],"en":["the organ that pumps blood","the central part"]}', NULL, 'at heart / heart of the matter', '[{"en":"Let''s get to the heart of the matter.","zh-TW":"讓我們切入問題核心。"},{"en":"He is a salesman at heart.","zh-TW":"他骨子裡是個業務員。"}]', '{"noun":"heart","adjective":"heartfelt","adjective2":"heartless"}', NULL, 2, 1533, NULL),
(1534, 'heavy', '/ˈhɛvi/', 'adjective', '{"zh-TW":["重的；大量的"],"en":["having great weight","large in amount"]}', NULL, 'heavy traffic / heavy workload', '[{"en":"There is heavy traffic during rush hour.","zh-TW":"尖峰時段交通很擁擠。"},{"en":"She has a heavy workload this month.","zh-TW":"她這個月工作量很大。"}]', '{"adjective":"heavy","adverb":"heavily","noun":"heaviness"}', NULL, 2, 1534, NULL),
(1535, 'hedge', '/hedʒ/', 'noun, verb', '{"zh-TW":["樹籬","對沖；規避風險"],"en":["a fence of bushes","to protect against financial loss"]}', NULL, 'hedge fund / hedge against risk', '[{"en":"Investors use gold to hedge against inflation.","zh-TW":"投資者用黃金來對沖通脹風險。"},{"en":"The garden was surrounded by a tall hedge.","zh-TW":"花園被高高的樹籬圍繞。"}]', '{"noun":"hedge","verb":"hedge"}', NULL, 2, 1535, NULL),
